"D"],"response_type":"multiple-choice"},{"id":"practice-test-5:math2-25","practice_test_id":"practice-test-5","subject":"math","module":"math2","question_number":25,"source_page":50,"answer_page":49,"correct_answer":"A","accepted_answers":["A"],"response_type":"multiple-choice"},{"id":"practice-test-5:math2-26","practice_test_id":"practice-test-5","subject":"math","module":"math2","question_number":26,"source_page":50,"answer_page":49,"correct_answer":"C","accepted_answers":["C"],"response_type":"multiple-choice"},{"id":"practice-test-5:math2-27","practice_test_id":"practice-test-5","subject":"math","module":"math2","question_number":27,"source_page":50,"answer_page":50,"correct_answer":"4176","accepted_answers":["4176"],"response_type":"student-produced"}]'::jsonb) as x(
