  subject=excluded.subject,
  module=excluded.module,
  question_number=excluded.question_number,
  source_page=excluded.source_page,
  answer_page=excluded.answer_page,
  correct_answer=excluded.correct_answer,
  accepted_answers=excluded.accepted_answers,
  response_type=excluded.response_type,
  updated_at=now();



update public.sat_question_bank q
set question_lines=x.question_lines,
    source_crop=x.source_crop,
    needs_visual=x.needs_visual,
    visual_crop=x.visual_crop,
    visual_after_line=x.visual_after_line,
    question_mode=x.question_mode,
    content_status=x.content_status,
    updated_at=now()
from jsonb_to_recordset('[{"id":"practice-test-5:math1-1","question_lines":["The graph of a system of a linear equation and a nonlinear equation is shown. What is the solution $(x,y)$ to this system?","A) $(0,0)$","B) $(0,4)$","C) $(4,5)$","D) $(5,0)$"],"source_crop":{"x":36,"y":116,"width":268,"height":320},"needs_visual":true,"visual_crop":{"x":0.04,"y":0.01,"width":0.84,"height":0.61},"visual_after_line":-1,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-2","question_lines":["On the first day of a semester, a film club has 90 members. Each day after the first day of the semester, 10 new members join the film club. If no members leave the film club, how many total members will the film club have 4 days after the first day of the semester?","A) 400","B) 130","C) 94","D) 90"],"source_crop":{"x":36,"y":518,"width":268,"height":172},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-3","question_lines":["The graph of the linear function $f$ is shown, where $y=f(x)$. What is the $y$-intercept of the graph of $f$?","A) $(0,0)$","B) $\\left(0,-\\frac{16}{11}\\right)$","C) $(0,-8)$","D) $(0,8)$"],"source_crop":{"x":318,"y":116,"width":267,"height":385},"needs_visual":true,"visual_crop":{"x":0.01,"y":0.01,"width":0.9,"height":0.5},"visual_after_line":-1,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-4","question_lines":["$$\\begin{aligned}s+7r&=27\\\\r&=3\\end{aligned}$$","What is the solution $(r,s)$ to the given system of equations?","A) $(6,3)$","B) $(3,6)$","C) $(3,27)$","D) $(27,3)$"],"source_crop":{"x":54,"y":116,"width":257,"height":165},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-5","question_lines":["The table shows selected values from function $f$.","x f(x)","−1 16","0 17","1 18","2 19","Which of the following is the best description of function $f$?","A) Decreasing linear","B) Increasing linear","C) Decreasing exponential","D) Increasing exponential"],"source_crop":{"x":54,"y":357,"width":257,"height":220},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-6","question_lines":["The graph of a system of linear equations is shown. The solution to the system is $(x,y)$. What is the value of $x$?"],"source_crop":{"x":318,"y":116,"width":267,"height":255},"needs_visual":true,"visual_crop":{"x":0.06,"y":0.01,"width":0.9,"height":0.76},"visual_after_line":-1,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-7","question_lines":["23, 27, 27, 32, 35, 36, 52","What is the range of the 7 scores shown?"],"source_crop":{"x":318,"y":448,"width":267,"height":66},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-8","question_lines":["Note: Figure not drawn to scale.","In the figure, line $m$ is parallel to line $n$, and line $k$ intersects both lines. Which of the following statements is true?","A) The value of $x$ is less than 145.","B) The value of $x$ is greater than 145.","C) The value of $x$ is equal to 145.","D) The value of $x$ cannot be determined."],"source_crop":{"x":36,"y":116,"width":268,"height":326},"needs_visual":true,"visual_crop":{"x":0.05,"y":0.01,"width":0.88,"height":0.56},"visual_after_line":-1,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-9","question_lines":["The equation $x+y=1{,}440$ represents the number of minutes of daylight (between sunrise and sunset), $x$, and the number of minutes of non-daylight, $y$, on a particular day in Oak Park, Illinois. If this day has 670 minutes of daylight, how many minutes of non-daylight does it have?","A) 670","B) 770","C) 1,373","D) 1,440"],"source_crop":{"x":36,"y":519,"width":268,"height":174},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-10","question_lines":["Scott selected 20 employees at random from all 400 employees at a company. He found that 16 of the employees in this sample are enrolled in exactly three professional development courses this year. Based on Scott’s findings, which of the following is the best estimate of the number of employees at the company who are enrolled in exactly three professional development courses this year?","A) 4","B) 320","C) 380","D) 384"],"source_crop":{"x":318,"y":116,"width":267,"height":190},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-11","question_lines":["If $4x-28=-24$, what is the value of $x-7$?","A) −24","B) −22","C) −6","D) −1"],"source_crop":{"x":318,"y":386,"width":267,"height":116},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-12","question_lines":["For a snowstorm in a certain town, the minimum rate of snowfall recorded was 0.6 inches per hour, and the maximum rate of snowfall recorded was 1.8 inches per hour. Which inequality is true for all values of $s$, where $s$ represents a rate of snowfall, in inches per hour, recorded for this snowstorm?","A) $s\\ge2.4$","B) $s\\ge1.8$","C) $0\\le s\\le0.6$","D) $0.6\\le s\\le1.8$"],"source_crop":{"x":54,"y":116,"width":257,"height":178},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-13","question_lines":["$$\\begin{aligned}y&=4x\\\\y&=x^2-12\\end{aligned}$$","A solution to the given system of equations is $(x,y)$, where $x>0$. What is the value of $x$?"],"source_crop":{"x":54,"y":366,"width":257,"height":98},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-14","question_lines":["A store sells two different-sized containers of blueberries. The store’s sales of these blueberries totaled 896.86 dollars last month. The equation $4.51x+6.07y=896.86$ represents this situation, where $x$ is the number of smaller containers sold and $y$ is the number of larger containers sold. According to the equation, what is the price, in dollars, of each smaller container?"],"source_crop":{"x":318,"y":116,"width":267,"height":148},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-15","question_lines":["A right circular cylinder has a base diameter of 22 centimeters and a height of 6 centimeters. What is the volume, in cubic centimeters, of the cylinder?","A) $132\\pi$","B) $264\\pi$","C) $726\\pi$","D) $2{,}904\\pi$"],"source_crop":{"x":318,"y":332,"width":267,"height":142},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-16","question_lines":[],"source_crop":{"x":36,"y":116,"width":549,"height":614},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"image-fallback","content_status":"verified"},{"id":"practice-test-5:math1-17","question_lines":["At a particular track meet, the ratio of coaches to athletes is 1 to 26. If there are $x$ coaches at the track meet, which of the following expressions represents the number of athletes at the track meet?","A) $\\frac{x}{26}$","B) $26x$","C) $x+26$","D) $\\frac{26}{x}$"],"source_crop":{"x":54,"y":116,"width":257,"height":214},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-18","question_lines":["Kaylani used fabric measuring 5 yards in length to make each suit for a men’s choir. The relationship between the number of suits that Kaylani made, $x$, and the total length of fabric that she purchased, $y$, in yards, is represented by the equation $y-5x=6$. What is the best interpretation of 6 in this context?","A) Kaylani made 6 suits.","B) Kaylani purchased a total of 6 yards of fabric.","C) Kaylani used a total of 6 yards of fabric to make the suits.","D) Kaylani purchased 6 yards more fabric than she used to make the suits."],"source_crop":{"x":54,"y":403,"width":257,"height":208},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-19","question_lines":["What is the value of $\\tan\\left(\\frac{92\\pi}{3}\\right)$?","A) $-\\sqrt{3}$","B) $-\\frac{\\sqrt{3}}{3}$","C) $\\frac{\\sqrt{3}}{3}$","D) $\\sqrt{3}$"],"source_crop":{"x":318,"y":116,"width":267,"height":198},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-20","question_lines":["Note: Figure not drawn to scale.","In the triangle shown, what is the value of $\\cos x^\\circ$?"],"source_crop":{"x":318,"y":390,"width":267,"height":208},"needs_visual":true,"visual_crop":{"x":0.1,"y":0.02,"width":0.84,"height":0.69},"visual_after_line":-1,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-21","question_lines":["The function $g$ is defined by $g(x)=(x+14)(t-x)$, where $t$ is a constant. In the $xy$-plane, the graph of $y=g(x)$ passes through the point $(24,0)$. What is the value of $g(0)$?"],"source_crop":{"x":36,"y":116,"width":268,"height":88},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-22","question_lines":["$$(x+4)^2+(y-19)^2=121$$","The graph of the given equation is a circle in the $xy$-plane. The point $(a,b)$ lies on the circle. Which of the following is a possible value for $a$?","A) −16","B) −14","C) 11","D) 19"],"source_crop":{"x":36,"y":280,"width":268,"height":170},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-23","question_lines":["A right rectangular prism has a height of 9 inches. The length of the prism’s base is $x$ inches, which is 7 inches more than the width of the prism’s base. Which function $V$ gives the volume of the prism, in cubic inches, in terms of the length of the prism’s base?","A) $V(x)=x(x+9)(x+7)$","B) $V(x)=x(x+9)(x-7)$","C) $V(x)=9x(x+7)$","D) $V(x)=9x(x-7)$"],"source_crop":{"x":318,"y":116,"width":267,"height":178},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-24","question_lines":["Which of the following functions has(have) a minimum value at −3?","I. $f(x)=-6(3)^x-3$","II. $g(x)=-3(6)^x$","A) I only","B) II only","C) I and II","D) Neither I nor II"],"source_crop":{"x":318,"y":369,"width":267,"height":165},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-25","question_lines":["The result of increasing the quantity $x$ by 400% is 60. What is the value of $x$?","A) 12","B) 15","C) 240","D) 340"],"source_crop":{"x":54,"y":116,"width":257,"height":128},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-26","question_lines":["The function $f$ is defined by $f(x)=ax^2+bx+c$, where $a$, $b$, and $c$ are constants. The graph of $y=f(x)$ in the $xy$-plane passes through the points $(7,0)$ and $(-3,0)$. If $a$ is an integer greater than 1, which of the following could be the value of $a+b$?","A) −6","B) −3","C) 4","D) 5"],"source_crop":{"x":54,"y":316,"width":257,"height":188},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"},{"id":"practice-test-5:math1-27","question_lines":["The function $g$ is defined by $g(x)=x(x-2)(x+6)^2$. The value of $g(7-w)$ is 0, where $w$ is a constant. What is the sum of all possible values of $w$?"],"source_crop":{"x":318,"y":116,"width":267,"height":94},"needs_visual":false,"visual_crop":null,"visual_after_line":null,"question_mode":"text","content_status":"verified"}]'::jsonb) as x(
  id text,question_lines jsonb,source_crop jsonb,needs_visual boolean,
  visual_crop jsonb,visual_after_line integer,question_mode text,content_status text
)
where q.id=x.id and q.practice_test_id='practice-test-5';



